 async function add(files){const owner=current();for(const file of files){if(owner.documents.length>=limits.files)throw new Error('W jednej sprawie można dodać do 40 dokumentów.');if(!/\.pdf$/i.test(file.name)||file.type&&!['application/pdf','application/octet-stream'].includes(file.type))throw new Error('Wybierz dokumenty w formacie PDF.');if(file.size>limits.fileBytes)throw new Error('Pojedynczy PDF może mieć do 32 MB.');if(owner.documents.reduce((s,d)=>s+d.file.size,0)+file.size>limits.totalBytes)throw new Error('Zestaw przekracza 180 MB. Podziel dokumenty na sprawy.');const head=new TextDecoder().decode(await file.slice(0,1024).arrayBuffer());if(!head.includes('%PDF-'))throw new Error('Ten plik nie ma prawidłowego nagłówka PDF.');const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer())),v=>v.toString(16).padStart(2,'0')).join('');if(owner.documents.some(d=>d.hash===hash)){owner.notice='Ten sam dokument jest już w tej sprawie.';continue;}const doc={id:crypto.randomUUID(),file,hash,token:0,status:'queued',pages:[],warnings:[],pageCount:null,progress:0};owner.documents.push(doc);enqueue(doc,owner);}emit();return queue;}
